    const initAudio = () => {
      initAudioContext();
      window.removeEventListener("click", initAudio);
    };

    window.addEventListener("click", initAudio);

    // Show help modal on first visit
    const hasSeenHelp = localStorage.getItem("pianoHelpSeen");
