          blendMode: 'screen',
          shape: 'circle'
        }
      },
      {
        type: 'waveform',
        enabled: true,
        intensity: 1.0,
        speed: 1.0,
        scale: 1.0,
        opacity: 0.6,
        beatReactive: false,
        frequencyReactive: false,
        colorCycling: false
      }
    ];
  }

  static getThemes(): VisualTheme[] {
    return [
      {
        id: 'dark-club',
        name: 'Dark Club',
        primaryColor: '#00d4ff',
        secondaryColor: '#ff0080',
        accentColor: '#ffff00',
        backgroundColor: '#000000',
        gradientColors: ['#000428', '#004e92'],
        particleColor: '#00d4ff',
        waveformColor: '#00ff88',
        spectrumColors: ['#ff0080', '#ff4000', '#ffff00', '#00ff88', '#00d4ff'],
        glowIntensity: 0.8,
        saturation: 1.0,
        brightness: 1.0,
        contrast: 1.2
      },
      {
        id: 'neon-cyber',
        name: 'Neon Cyber',
        primaryColor: '#ff00ff',
        secondaryColor: '#00ffff',
        accentColor: '#ffff00',
        backgroundColor: '#0a0a0a',
        gradientColors: ['#1a0033', '#330066'],
        particleColor: '#ff00ff',
