import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Slider } from '@/components/ui/slider';
import { Switch } from '@/components/ui/switch';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Badge } from '@/components/ui/badge';
import { 
  Palette, 
  Sliders, 
  Zap, 
  Monitor, 
  Save, 
  Upload, 
  RotateCcw, 
  Eye,
  Settings2,
  Paintbrush,
  Gauge,
  Sparkles,
  Volume2
} from 'lucide-react';

interface VisualizationControlsProps {
  onSettingsChange: (category: string, settings: any) => void;
  currentSettings: VisualizationSettings;
  className?: string;
}

interface VisualizationSettings {
  theme: {
    name: string;
    primaryColor: string;
    secondaryColor: string;
    accentColor: string;
    backgroundColor: string;
    colorMode: 'gradient' | 'frequency' | 'energy' | 'beat';
    saturation: number;
    brightness: number;
    contrast: number;
  };
  effects: {
    particles: {
      enabled: boolean;
      count: number;
      size: number;
      speed: number;
      life: number;
      shape: 'circle' | 'square' | 'triangle' | 'star' | 'diamond';
      blendMode: 'normal' | 'screen' | 'multiply' | 'overlay';
      trail: boolean;
      trailLength: number;
    };
    waveform: {
      enabled: boolean;
      style: 'line' | 'filled' | 'mirror' | 'radial';
      thickness: number;
      smoothing: number;
      colorMode: 'solid' | 'gradient' | 'frequency';
      beatPulse: boolean;
    };
    spectrum: {
      enabled: boolean;
      bars: number;
      logScale: boolean;
      peakHold: boolean;
      smoothing: number;
      colorMode: 'gradient' | 'frequency' | 'energy';
      beatReactive: boolean;
    };
    visual3d: {
      enabled: boolean;
      type: 'tunnel' | 'plasma' | 'kaleidoscope' | 'lightning';
      intensity: number;
      speed: number;
      rotation: boolean;
      morphing: boolean;
    };
  };
  performance: {
    quality: 'low' | 'medium' | 'high' | 'ultra';
    targetFps: number;
    enableWebGL: boolean;
    enablePostProcessing: boolean;
    enableMotionBlur: boolean;
    enableBloom: boolean;
    antiAliasing: boolean;
  };
  reactivity: {
    beatSensitivity: number;
    frequencySensitivity: number;
    energyThreshold: number;
    beatPrediction: boolean;
    autoAdjust: boolean;
    transientDetection: boolean;
    keySync: boolean;
  };
  display: {
    showBeatIndicator: boolean;
    showBpmCounter: boolean;
    showFrequencyBands: boolean;
    showEnergyMeter: boolean;
    showPerformanceStats: boolean;
    fullScreenMode: boolean;
    multiMonitor: boolean;
  };
}

const COLOR_THEMES = [
  {
    name: 'Dark Club',
    id: 'dark-club',
    primary: '#00d4ff',
    secondary: '#ff0080',
    accent: '#ffff00',
    background: '#000000'
  },
  {
    name: 'Neon Cyber',
    id: 'neon-cyber',
    primary: '#ff00ff',
    secondary: '#00ffff',
    accent: '#ffff00',
    background: '#0a0a0a'
  },
  {
    name: 'Retro Synthwave',
    id: 'retro-synthwave',
    primary: '#ff6ec7',
    secondary: '#7928ca',
    accent: '#ffd700',
    background: '#0f0f23'
  },
  {
    name: 'Minimal Pro',
    id: 'minimal-pro',
    primary: '#3b82f6',
    secondary: '#1d4ed8',
    accent: '#f59e0b',
    background: '#111827'
  },
  {
    name: 'Warm Sunset',
    id: 'warm-sunset',
    primary: '#ff6b35',
    secondary: '#f7931e',
    accent: '#ffcd3c',
    background: '#1a1a2e'
  },
  {
    name: 'Cool Ocean',
    id: 'cool-ocean',
    primary: '#0077be',
    secondary: '#00a8cc',
    accent: '#00c9cc',
    background: '#001122'
  }
];

export default function VisualizationControls({
  onSettingsChange,
  currentSettings,
  className = ''
}: VisualizationControlsProps) {
  const [activeTab, setActiveTab] = useState<string>('theme');
  const [presetName, setPresetName] = useState<string>('');
  const [showAdvanced, setShowAdvanced] = useState<boolean>(false);

  // Auto-save settings
  const [autoSave, setAutoSave] = useState<boolean>(true);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);

  // Performance monitoring
  const [performanceScore, setPerformanceScore] = useState<number>(85);
  const [optimizationSuggestions, setOptimizationSuggestions] = useState<string[]>([]);

  useEffect(() => {
    if (autoSave) {
      const timer = setTimeout(() => {
        saveSettings();
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [currentSettings, autoSave]);

  const saveSettings = () => {
    // Save settings to localStorage
    localStorage.setItem('dj-visual-settings', JSON.stringify(currentSettings));
    setLastSaved(new Date());
  };

  const loadSettings = () => {
    const saved = localStorage.getItem('dj-visual-settings');
    if (saved) {
      try {
        const settings = JSON.parse(saved);
        Object.keys(settings).forEach(category => {
          onSettingsChange(category, settings[category]);
        });
      } catch (error) {
        console.error('Failed to load settings:', error);
      }
    }
  };

  const resetSettings = () => {
    // Reset to defaults
    const defaultSettings: VisualizationSettings = {
      theme: {
        name: 'Dark Club',
